      const gzDay = info.ganzhi && info.ganzhi.day
      const gzHour = info.ganzhi && info.ganzhi.hour
      const gzText = gzDay ? gzDay.name + '日' + (gzHour ? ' · ' + gzHour.name : '') : ''
      const caption = info.ganzhi.year + '年 '
